  qs: [
    { q: "Why was Jean Valjean originally sent to prison?", o: ["For attacking a bishop", "For stealing bread for his sister's children", "For forging a passport", "For leading a riot"], a: 1, ex: "الجواز الأصفر يقول إنه سُجن خمس سنوات لكسر نافذة خبّاز وسرقة رغيف لأبناء أخته." },
    { q: "What does the bishop do when the gendarmes bring Valjean back?", o: ["He presses charges at once", "He pretends not to know him", "He says he also gave him the candlesticks", "He asks for the silver to be returned"], a: 2, ex: "قال إنه نسي عنده الشمعدانين أيضًا، فأطلق الدرك سراحه." },
    { q: "Why does Monsieur Madeleine go to the trial at Arras?", o: ["To watch Javert fail", "To buy the factory of a rival", "To stop an innocent man being condemned in his place", "To find Cosette"], a: 2, ex: "ذهب ليخبر المحكمة من هو، لئلا يُدان شامباتيو البريء بدلًا عنه." },
    { q: "Which of these happens last?", o: ["Valjean carries Marius through the sewers", "Valjean frees Javert at the barricade", "Valjean takes Cosette from the Thenardiers", "Valjean confesses his past to Marius"], a: 3, ex: "اعترافه لماريوس يقع بعد العرس، أي بعد كل الأحداث الأخرى المذكورة." },
    { q: "Why can Javert not go on living?", o: ["He has been dismissed from the police", "Mercy from a criminal destroys the only system he understands", "He is wounded at the barricade", "He has lost his notebook"], a: 1, ex: "رحمة المجرم به حطّمت النظام الوحيد الذي كان يفهم به العالم، ولم يكن يطيق العيش مع سؤال." },
    { q: "What is the novel's central moral claim?", o: ["Laws should always be obeyed exactly", "Poverty is a personal failing", "An act of undeserved mercy can remake a whole life", "Revolutions always succeed"], a: 2, ex: "كرم الأسقف غير المستحق هو الذي صنع جان فالجان الجديد، وعليه تقوم الرواية كلها." }
  ],
  moral: "الرحمة التي لا يستحقها صاحبها قد تصنع منه إنسانًا جديدًا، والعدل بلا رحمة يهدم صاحبه قبل غيره."
